// src/data/vehicles.ts
// FALLBACK: datos locales usados mientras Sanity no está configurado
// Una vez que Sanity esté conectado, estos datos son reemplazados por el hook useVehicles()

export type Vehicle = {
  id: number;
  brand: string;
  model: string;
  year: number;
  images: string[];
  condition: "new" | "used";
  mileage?: number;
  fuel: string;
  priceUsd?: number;
  transmission?: string;
  drivetrain?: string;
  bodyType?: string;
  engine?: string;
  powerHp?: number;
  torqueNm?: number;
  doors?: number;
  color?: string;
};

// Todos los vehículos fueron migrados a Sanity.
export const vehicles: Vehicle[] = [];
